     4→using System;
     5→using System.Runtime.CompilerServices;
     6→using Microsoft.Extensions.ObjectPool;
     7→using Nethermind.Core;
     8→using Nethermind.Serialization.Rlp.TxDecoders;
     9→
    10→namespace Nethermind.Serialization.Rlp;
    11→
    12→[Rlp.SkipGlobalRegistration]
    13→public sealed class TxDecoder : TxDecoder<Transaction>
    14→{
    15→    public static readonly ObjectPool<Transaction> TxObjectPool;
    16→
    17→    public static readonly TxDecoder Instance;
    18→
    19→    private TxDecoder(Func<Transaction> transactionFactory) : base(transactionFactory) { }
    20→
    21→    static TxDecoder()
    22→    {
    23→        TxObjectPool = new DefaultObjectPool<Transaction>(new Transaction.PoolPolicy(), Environment.ProcessorCount * 4);
    24→        Instance = new TxDecoder(static () => TxObjectPool.Get());
    25→        Rlp.RegisterDecoder(typeof(Transaction), Instance);
    26→    }
    27→}
    28→
    29→public sealed class SystemTxDecoder : TxDecoder<SystemTransaction>;
    30→public sealed class GeneratedTxDecoder : TxDecoder<GeneratedTransaction>;
    31→
    32→public class TxDecoder<T> : IRlpStreamDecoder<T>, IRlpValueDecoder<T> where T : Transaction, new()
    33→{
    34→    private readonly ITxDecoder?[] _decoders = new ITxDecoder?[Transaction.MaxTxType + 1];
    35→
    36→    protected TxDecoder(Func<T>? transactionFactory = null)
    37→    {
    38→        Func<T> factory = transactionFactory ?? (static () => new T());
    39→        RegisterDecoder(new LegacyTxDecoder<T>(factory));
    40→        RegisterDecoder(new AccessListTxDecoder<T>(factory));
    41→        RegisterDecoder(new EIP1559TxDecoder<T>(factory));
    42→        RegisterDecoder(new BlobTxDecoder<T>(factory));
    43→        RegisterDecoder(new SetCodeTxDecoder<T>(factory));
    44→    }
    45→
    46→    public void RegisterDecoder(ITxDecoder decoder) => _decoders[(int)decoder.Type] = decoder;
    47→
    48→    public T? Decode(RlpStream rlpStream, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
    49→    {
    50→        static void ThrowIfLegacy(TxType txType1)
    51→        {
    52→            if (txType1 == TxType.Legacy)
    53→            {
    54→                throw new RlpException("Legacy transactions are not allowed in EIP-2718 Typed Transaction Envelope");
    55→            }
    56→        }
    57→
    58→        if (rlpStream.IsNextItemNull())
    59→        {
    60→            rlpStream.ReadByte();
    61→            return null;
    62→        }
    63→
    64→        Span<byte> transactionSequence = rlpStream.PeekNextItem();
    65→        TxType txType = TxType.Legacy;
    66→        if (rlpBehaviors.HasFlag(RlpBehaviors.SkipTypedWrapping))
    67→        {
    68→            if (rlpStream.PeekByte() <= Transaction.MaxTxType) // it is typed transactions
    69→            {
    70→                transactionSequence = rlpStream.Peek(rlpStream.Length);
    71→                txType = (TxType)rlpStream.ReadByte(); // read tx type
    72→                ThrowIfLegacy(txType);
    73→            }
    74→        }
    75→        else if (!rlpStream.IsSequenceNext())
    76→        {
    77→            (int _, int contentLength) = rlpStream.ReadPrefixAndContentLength();
    78→            transactionSequence = rlpStream.Peek(contentLength);
    79→            txType = (TxType)rlpStream.ReadByte();
    80→            ThrowIfLegacy(txType);
    81→        }
    82→
    83→        return (T)GetDecoder(txType).Decode(transactionSequence, rlpStream, rlpBehaviors);
    84→    }
    85→
    86→    private ITxDecoder GetDecoder(TxType txType) =>
    87→        _decoders.TryGetByTxType(txType, out ITxDecoder decoder)
    88→            ? decoder
    89→            : throw new RlpException($"Unknown transaction type {txType}") { Data = { { "txType", txType } } };
    90→
    91→    public T? Decode(ref Rlp.ValueDecoderContext decoderContext, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
    92→    {
    93→        T transaction = null;
    94→        Decode(ref decoderContext, ref transaction, rlpBehaviors);
    95→        return transaction;
    96→    }
    97→
    98→    public void Decode(ref Rlp.ValueDecoderContext decoderContext, ref T? transaction, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
    99→    {
   100→        if (decoderContext.IsNextItemNull())
   101→        {
   102→            decoderContext.ReadByte();
   103→            transaction = null;
   104→            return;
   105→        }
   106→
   107→        int txSequenceStart = decoderContext.Position;
   108→        ReadOnlySpan<byte> transactionSequence = decoderContext.PeekNextItem();
   109→
   110→        TxType txType = TxType.Legacy;
   111→        if (rlpBehaviors.HasFlag(RlpBehaviors.SkipTypedWrapping))
   112→        {
   113→            if (decoderContext.PeekByte() <= Transaction.MaxTxType) // it is typed transactions
   114→            {
   115→                txSequenceStart = decoderContext.Position;
   116→                transactionSequence = decoderContext.Peek(decoderContext.Length);
   117→                txType = (TxType)decoderContext.ReadByte();
   118→            }
   119→        }
   120→        else
   121→        {
   122→            if (!decoderContext.IsSequenceNext())
   123→            {
   124→                (_, int contentLength) = decoderContext.ReadPrefixAndContentLength();
   125→                txSequenceStart = decoderContext.Position;
   126→                transactionSequence = decoderContext.Peek(contentLength);
   127→                txType = (TxType)decoderContext.ReadByte();
   128→            }
   129→        }
   130→
   131→        GetDecoder(txType).Decode(ref Unsafe.As<T, Transaction>(ref transaction), txSequenceStart, transactionSequence, ref decoderContext, rlpBehaviors);
   132→    }
   133→
   134→    public Rlp Encode(T item, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
   135→    {
   136→        RlpStream rlpStream = new(GetLength(item, rlpBehaviors));
   137→        Encode(rlpStream, item, rlpBehaviors);
   138→        return new Rlp(rlpStream.Data.ToArray() ?? []);
